#!/usr/bin/env bash
# Remove files generated by agent-config.
set -euo pipefail

SCRIPT_NAME="uninstall"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=common.sh
source "$REPO_ROOT/scripts/common.sh"

usage() {
  cat <<'USAGE'
Usage: ./scripts/uninstall.sh [--skills|--rules] [--all|--cursor|--claude|--agents]
                             [--external-skill <config.json>]

Remove this repo's managed skills, supporting resources, and generated rules.
External skills require their explicit config and agent targets; defaults preserve them.
USAGE
}

WANTS_SKILLS=0
WANTS_RULES=0
ARTIFACT_FLAGS=0
WANTS_CURSOR=0
WANTS_CLAUDE=0
WANTS_AGENTS=0
TARGET_FLAGS=0
ALL_TARGETS=0
EXTERNAL_SKILL=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --skills) WANTS_SKILLS=1; ARTIFACT_FLAGS=$((ARTIFACT_FLAGS + 1)) ;;
    --rules) WANTS_RULES=1; ARTIFACT_FLAGS=$((ARTIFACT_FLAGS + 1)) ;;
    --all) ALL_TARGETS=1 ;;
    --cursor) WANTS_CURSOR=1; TARGET_FLAGS=$((TARGET_FLAGS + 1)) ;;
    --claude) WANTS_CLAUDE=1; TARGET_FLAGS=$((TARGET_FLAGS + 1)) ;;
    --agents|--codex) WANTS_AGENTS=1; TARGET_FLAGS=$((TARGET_FLAGS + 1)) ;;
    --external-skill)
      shift
      [[ $# -gt 0 && -n "$1" && -z "$EXTERNAL_SKILL" ]] || die "--external-skill requires one config path"
      EXTERNAL_SKILL="$1"
      ;;
    -h|--help) usage; exit 0 ;;
    *) die "unknown option: $1 (try --help)" ;;
  esac
  shift
done

[[ $ALL_TARGETS -eq 0 || $TARGET_FLAGS -eq 0 ]] || die "--all cannot be combined with an agent target"
if [[ -n "$EXTERNAL_SKILL" ]]; then
  [[ $WANTS_RULES -eq 0 && $TARGET_FLAGS -gt 0 && $ALL_TARGETS -eq 0 ]] || die "external removal requires explicit agent targets and cannot combine with rules or --all"
  external_skill remove "$EXTERNAL_SKILL"
  exit 0
fi
[[ $ARTIFACT_FLAGS -ne 0 ]] || { WANTS_SKILLS=1; WANTS_RULES=1; }
if [[ $ALL_TARGETS -eq 1 || $TARGET_FLAGS -eq 0 ]]; then
  WANTS_CLAUDE=1
  WANTS_AGENTS=1
fi

remove_skill_links_from_root() {
  local root="$1" dir
  [[ -d "$root" ]] || return 0
  info "target $root"
  for dir in "$root"/*; do
    [[ -d "$dir" && ! -L "$dir" ]] || continue
    remove_managed_skill "$dir"
  done
}

remove_managed_file() {
  local dest="$1"
  if is_managed_rule_file "$dest"; then
    rm "$dest"
    info "removed $dest"
  fi
}

remove_managed_rules_in_dir() {
  local dir="$1" ext="$2" f
  [[ -d "$dir" ]] || return 0
  info "target $dir"
  for f in "$dir"/*."$ext"; do
    [[ -e "$f" || -L "$f" ]] || continue
    remove_managed_file "$f"
  done
}

# Validate owned reference trees before removing any installed files.
if [[ $WANTS_RULES -eq 1 ]]; then
  [[ $WANTS_CURSOR -eq 0 ]] || rule_references preflight "$(rule_reference_root "$CURSOR_RULES")" --sources "$RULES_ROOT"
  [[ $WANTS_CURSOR -eq 0 ]] || cursor_rule_context preflight
  [[ $WANTS_CLAUDE -eq 0 ]] || rule_references preflight "$(rule_reference_root "$CLAUDE_RULES")" --sources "$RULES_ROOT"
  [[ $WANTS_AGENTS -eq 0 ]] || rule_references preflight "$(rule_reference_root "$CODEX_AGENTS")" --sources "$RULES_ROOT"
fi

if [[ $WANTS_SKILLS -eq 1 ]]; then
  [[ $WANTS_CURSOR -eq 0 ]] || remove_skill_links_from_root "$CURSOR_SKILLS"
  [[ $WANTS_CLAUDE -eq 0 ]] || remove_skill_links_from_root "$CLAUDE_SKILLS"
  [[ $WANTS_AGENTS -eq 0 ]] || remove_skill_links_from_root "$CODEX_SKILLS"
fi
if [[ $WANTS_RULES -eq 1 ]]; then
  [[ $WANTS_CURSOR -eq 0 ]] || cursor_rule_context remove
  [[ $WANTS_CURSOR -eq 0 ]] || rule_references remove "$(rule_reference_root "$CURSOR_RULES")" --sources "$RULES_ROOT"
  [[ $WANTS_CLAUDE -eq 0 ]] || rule_references remove "$(rule_reference_root "$CLAUDE_RULES")" --sources "$RULES_ROOT"
  [[ $WANTS_AGENTS -eq 0 ]] || rule_references remove "$(rule_reference_root "$CODEX_AGENTS")" --sources "$RULES_ROOT"
  [[ $WANTS_CURSOR -eq 0 ]] || remove_managed_rules_in_dir "$CURSOR_RULES" mdc
  [[ $WANTS_CLAUDE -eq 0 ]] || { remove_managed_rules_in_dir "$CLAUDE_RULES" md; remove_managed_file "$CLAUDE_MD"; }
  [[ $WANTS_AGENTS -eq 0 ]] || { info "target $CODEX_AGENTS"; remove_managed_file "$CODEX_AGENTS"; }
fi

info "done"
